#!/usr/bin/env python3
"""protein/proteinmpnn_redesign — auto-generated run.py (archetype=mutation_scan).

第一版只实现 simulate 模式:从 stdin/args 拿 inputs,产合理合成数据 JSON。
真实现路径(simulate=False)留 stub:返回 not-implemented + 提示。

输入契约:
  stdin JSON,字段按 SKILL.md 的 inputs 段;simulate 默认 true。
  CLI 兜底:--simulate / 各位置参数。

输出:
  stdout JSON;失败时也写 JSON {"ok": false, "error": "..."} 而非裸 traceback。
"""
import json
import sys

ARCHETYPE = "mutation_scan"
BRAIN = "protein"
SKILL = "proteinmpnn_redesign"

def simulate(payload):
    """auto-generated by regen_simulate.py — outputs schema 来自 SKILL.md."""
    import copy
    import random
    random.seed(int(payload.get("seed", 42)) if isinstance(payload, dict) else 42)
    out = copy.deepcopy({'n_sequences_generated': 64, 'sequences': [{'id': 'S001', 'sequence': 'M...', 'score': -2.34, 'sequence_recovery': 0.42, 'passed_recovery': True}], 'freeze_check': {'all_frozen_preserved': True, 'violations': []}, 'provenance': {}})
    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({
                "simulated": True,
                "archetype": ARCHETYPE,
                "brain": BRAIN,
                "skill": SKILL,
            })
        if "skill_id" in out and not out["skill_id"]:
            out["skill_id"] = SKILL
    return out

def real(payload):
    """ProteinMPNN partial redesign:固定某些 position(active site),其余 redesign。
    输入额外:fixed_positions (list of int) / chain_letter (默认 'A')
    """
    import os as _os
    import tempfile as _tempfile
    import time as _time
    try:
        from brains._common.lib.run_tool import run_tool
    except ImportError:
        import sys as _sys
        _sys.path.insert(0, "/home/zkyd/data1/mzy/praxis2-brains")
        from _common.lib.run_tool import run_tool  # noqa: F401
    pdb = payload.get("input_pdb") or payload.get("backbone_pdb")
    fixed = payload.get("fixed_positions") or []
    chain = payload.get("chain_letter", "A")
    num_seq = int(payload.get("num_seq_per_target", 8))
    out_dir = payload.get("out_dir") or _tempfile.mkdtemp(prefix="proteinmpnn_redesign_")
    diagnostics = {"brain": BRAIN, "skill": SKILL, "archetype": ARCHETYPE,
                   "tool": "ProteinMPNN", "fixed_positions": fixed, "out_dir": out_dir}
    if _os.environ.get("PRAXIS_SKILL_DRY_HOST") == "1":
        return {"ok": True, "skill_id": SKILL, "wt_score": 0.0, "scan_csv": "",
                "top_mutations": [], "diagnostics": {**diagnostics, "dry": True}}
    if not pdb or not _os.path.isfile(pdb):
        return {"ok": False, "error": f"backbone PDB 不存在", "diagnostics": diagnostics}

    fixed_json = _os.path.join(out_dir, "fixed.json")
    _os.makedirs(out_dir, exist_ok=True)
    import json as _json
    pdb_id = _os.path.splitext(_os.path.basename(pdb))[0]
    with open(fixed_json, "w") as fh:
        _json.dump({pdb_id: {chain: list(fixed)}}, fh)
    cmd = ["python3", "/home/zkyd/data2/mzy/binaries/ProteinMPNN/protein_mpnn_run.py",
           "--pdb_path", pdb,
           "--pdb_path_chains", chain,
           "--out_folder", out_dir,
           "--num_seq_per_target", str(num_seq),
           "--fixed_positions_jsonl", fixed_json,
           "--sampling_temp", "0.1"]
    t0 = _time.time()
    r = run_tool(cmd, timeout=int(payload.get("timeout_s", 600)))
    diagnostics["subprocess"] = {"wall_sec": r.get("wall_sec"), "rc": r.get("returncode")}
    if not r["ok"]:
        return {"ok": False, "error": r.get("error", "ProteinMPNN redesign 失败"),
                "stderr": r.get("stderr", "")[-400:], "diagnostics": diagnostics}
    import glob as _glob
    fastas = sorted(_glob.glob(_os.path.join(out_dir, "seqs", "*.fa")))
    return {"ok": True, "skill_id": SKILL, "wt_score": 0.0, "scan_csv": "",
            "top_mutations": [{"position": 0, "from_aa": "", "to_aa": "",
                              "ddg": 0.0, "fasta": fastas[0] if fastas else ""}],
            "runtime_sec": round(_time.time() - t0, 2),
            "diagnostics": {**diagnostics, "fasta_files": fastas}}

def main():
    # stdin 优先(SkillExecTool 走 stdin)
    payload = {}
    if not sys.stdin.isatty():
        try:
            payload = json.load(sys.stdin)
            if not isinstance(payload, dict):
                payload = {}
        except json.JSONDecodeError:
            payload = {}
    if not payload:
        # 简易 CLI 兜底
        import argparse
        ap = argparse.ArgumentParser()
        ap.add_argument("--simulate", action="store_true", default=True)
        ap.add_argument("--seed", type=int, default=42)
        args, _ = ap.parse_known_args()
        payload = {"simulate": args.simulate, "seed": args.seed}

    simulate_mode = bool(payload.get("simulate", True))
    try:
        out = simulate(payload) if simulate_mode else real(payload)
    except Exception as e:
        out = {"ok": False, "error": f"run.py 内部错误: {e!r}"}

    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({"archetype": ARCHETYPE, "brain": BRAIN, "skill": SKILL})
    json.dump(out, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return 0

if __name__ == "__main__":
    sys.exit(main())
